import fs from 'fs'
import path from 'path'
import { ProjectItem, projectShapeError } from '../renderer/editor/project'
import { tr } from '../shared/locale'

/** Project on disk: renderer Project plus file id. */
export interface StoredProject {
  id: string
  version: 1
  name: string
  items: ProjectItem[]
}

/** Summary returned by `list()` (does not include all clips). */
export interface ProjectListEntry {
  id: string
  name: string
  updatedAt: number
  items: number
}

/** Project IDs allow filename-safe characters only (`p_` prefix is generated by the renderer). */
const ID_RE = /^[A-Za-z0-9_-]+$/
/** Values that look valid but are invalid, such as `String(undefined)`. */
const BAD_IDS = new Set(['undefined', 'null', 'NaN'])
/** Longest project name accepted by `rename` (mirrors the dialog's input limit). */
const MAX_NAME_LENGTH = 120
/** Maximum number of corrupt backups to retain per project. */
const MAX_BACKUPS = 3

export type ProjectErrorKind = 'save' | 'corrupt' | 'transient' | 'unsupported'

export function isValidId(id: unknown): id is string {
  return typeof id === 'string' && id.length > 0 && ID_RE.test(id) && !BAD_IDS.has(id)
}

/**
 * Reads and writes `%APPDATA%\Aditor\projects\<id>.json`.
 * Writes use a temporary file + fsync + rename (atomic replacement; preserve the previous version on failure).
 * On read, rename a file to `<id>.bak.<timestamp>.json` only for invalid JSON/format (never overwrite; keep the latest 3 backups).
 * Leave files untouched for transient read errors (EBUSY/EACCES, etc.) and preserve files from newer versions as-is.
 */
export class ProjectStore {
  private dir: string
  /** Most recent read/write failure message (cleared on success); displayed in the UI. */
  lastError: string | null = null
  lastErrorKind: ProjectErrorKind | null = null

  constructor(dir: string) {
    this.dir = dir
  }

  private setError(kind: ProjectErrorKind, message: string): void {
    this.lastErrorKind = kind
    this.lastError = message
  }

  private clearError(): void {
    this.lastErrorKind = null
    this.lastError = null
  }

  private filePath(id: string): string {
    if (!isValidId(id)) {
      throw new Error(tr('無效的專案 id：{id}', { id: String(id) }))
    }
    return path.join(this.dir, `${id}.json`)
  }

  /** Synchronous write (also used by the window-close flushSync path). */
  saveSync(p: StoredProject): void {
    let tmp = ''
    try {
      if (!p || typeof p !== 'object') throw new Error(tr('專案資料無效'))
      const file = this.filePath(p.id)
      const shape = projectShapeError(p)
      if (shape) throw new Error(tr('專案資料無效：{message}', { message: shape.message }))
      tmp = `${file}.tmp`
      fs.mkdirSync(this.dir, { recursive: true })
      const fd = fs.openSync(tmp, 'w')
      try {
        fs.writeSync(fd, JSON.stringify(p, null, 2), null, 'utf-8')
        fs.fsyncSync(fd)
      } finally {
        fs.closeSync(fd)
      }
      fs.renameSync(tmp, file)
      this.clearError()
    } catch (err) {
      this.setError('save', tr('儲存專案失敗：{message}', { message: (err as Error).message }))
      if (tmp) {
        try {
          fs.unlinkSync(tmp)
        } catch {}
      }
      throw err
    }
  }

  async save(p: StoredProject): Promise<void> {
    this.saveSync(p)
  }

  async load(id: string): Promise<StoredProject | null> {
    const file = this.filePath(id)
    let raw: string
    try {
      raw = fs.readFileSync(file, 'utf-8')
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null
      // Transient error (file in use/permission): do not rename or delete; retry next time.
      this.setError('transient', tr('暫時無法讀取專案檔（{id}.json）：{message}', { id, message: (err as Error).message }))
      return null
    }
    let data: unknown
    try {
      data = JSON.parse(raw)
    } catch (err) {
      this.quarantine(id, file, (err as Error).message)
      return null
    }
    const shape = projectShapeError(data)
    if (shape?.kind === 'unsupported') {
      this.setError('unsupported', tr('專案檔 {id}.json：{message}', { id, message: shape.message }))
      return null
    }
    if (shape) {
      this.quarantine(id, file, shape.message)
      return null
    }
    return { ...(data as StoredProject), id }
  }

  /** Rename a corrupt file to a unique backup name and retain only the latest MAX_BACKUPS files. */
  private quarantine(id: string, file: string, reason: string): void {
    this.setError('corrupt', tr('專案檔損毀（{id}.json）：{reason}', { id, reason }))
    try {
      let ts = Date.now()
      let dest = path.join(this.dir, `${id}.bak.${ts}.json`)
      while (fs.existsSync(dest)) {
        ts += 1
        dest = path.join(this.dir, `${id}.bak.${ts}.json`)
      }
      fs.renameSync(file, dest)
      this.pruneBackups(id)
    } catch {}
  }

  private pruneBackups(id: string): void {
    const prefix = `${id}.bak.`
    const re = /^(\d+)\.json$/
    const baks = fs
      .readdirSync(this.dir)
      .filter((n) => n.startsWith(prefix))
      .map((n) => ({ n, ts: Number(re.exec(n.slice(prefix.length))?.[1]) }))
      .filter((x) => Number.isFinite(x.ts))
      .sort((a, b) => b.ts - a.ts)
    for (const old of baks.slice(MAX_BACKUPS)) {
      try {
        fs.unlinkSync(path.join(this.dir, old.n))
      } catch {}
    }
  }

  async list(): Promise<ProjectListEntry[]> {
    this.clearError()
    let names: string[]
    try {
      names = fs.readdirSync(this.dir)
    } catch {
      return []
    }
    const entries: ProjectListEntry[] = []
    for (const name of names) {
      if (!name.endsWith('.json') || name.includes('.bak.')) continue
      const id = name.slice(0, -'.json'.length)
      if (!isValidId(id)) continue
      const file = path.join(this.dir, name)
      try {
        const stat = fs.statSync(file)
        const data = JSON.parse(fs.readFileSync(file, 'utf-8'))
        const shape = projectShapeError(data)
        if (shape) {
          this.setError(shape.kind === 'unsupported' ? 'unsupported' : 'corrupt', tr('專案檔 {name}：{message}', { name, message: shape.message }))
          continue
        }
        entries.push({ id, name: data.name, updatedAt: stat.mtimeMs, items: data.items.length })
      } catch (err) {
        // Leave corrupt files for load() to back up; list() records only the error.
        this.setError('corrupt', tr('專案檔損毀（{name}）：{message}', { name, message: (err as Error).message }))
      }
    }
    entries.sort((a, b) => b.updatedAt - a.updatedAt)
    return entries
  }

  /** Rename a stored project in place. Returns false when the project is missing, unreadable, or the name is blank. */
  async rename(id: string, name: string): Promise<boolean> {
    const trimmed = typeof name === 'string' ? name.trim() : ''
    if (!trimmed || trimmed.length > MAX_NAME_LENGTH) return false
    const project = await this.load(id)
    if (!project) return false
    await this.save({ ...project, name: trimmed })
    return true
  }

  async remove(id: string): Promise<void> {
    try {
      fs.unlinkSync(this.filePath(id))
    } catch (err) {
      // Treat a missing file as already deleted.
      if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err
    }
  }
}
